<?php declare(strict_types=1); $title = 'Compras'; ?>
<section>
    <div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold uppercase tracking-wide text-emerald-700">Abastecimiento</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Compras</h1><p class="mt-2 text-sm text-slate-600">Registra ingresos por proveedor y consulta su historial.</p></div><?php if (can('compras.crear')): ?><a href="<?= e($baseUrl) ?>/compras/nueva" class="inline-flex min-h-11 items-center justify-center rounded-lg bg-emerald-700 px-4 py-2 text-sm font-semibold text-white">Registrar compra</a><?php endif; ?></div>
    <?php if ($success): ?><div role="status" class="mb-5 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-900"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div role="alert" class="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><?= e($error) ?></div><?php endif; ?>
    <form method="get" action="<?= e($baseUrl) ?>/compras" class="mb-5 flex gap-3 rounded-xl border border-slate-200 bg-white p-4"><input name="q" value="<?= e($search) ?>" maxlength="100" placeholder="Buscar por proveedor, documento o número" class="min-h-11 flex-1 rounded-lg border border-slate-300 px-3 text-sm"><button class="rounded-lg border border-slate-300 px-4 text-sm font-semibold">Buscar</button></form>
    <div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-600"><tr><?php foreach (['Compra', 'Fecha', 'Proveedor', 'Documento', 'Líneas', 'Total', 'Estado', 'Registró', ''] as $label): ?><th class="px-4 py-3"><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100">
    <?php if (!$purchases): ?><tr><td colspan="9" class="px-4 py-10 text-center text-slate-500">No hay compras registradas.</td></tr><?php endif; ?>
    <?php foreach ($purchases as $purchase): ?><tr><td class="px-4 py-3 font-semibold">#<?= e($purchase['id']) ?></td><td class="px-4 py-3"><?= e(date('d/m/Y H:i', strtotime($purchase['fecha']))) ?></td><td class="px-4 py-3"><?= e($purchase['proveedor']) ?></td><td class="px-4 py-3"><?= e($purchase['numero_documento'] ?: '—') ?></td><td class="px-4 py-3"><?= e($purchase['lineas']) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float) $purchase['total'], 2)) ?></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-xs <?= $purchase['estado'] === 'registrada' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-200 text-slate-700' ?>"><?= e(ucfirst($purchase['estado'])) ?></span></td><td class="px-4 py-3"><?= e($purchase['usuario']) ?></td><td class="px-4 py-3"><a class="font-semibold text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/compras/detalle?id=<?= e($purchase['id']) ?>">Ver detalle</a></td></tr><?php endforeach; ?>
    </tbody></table></div>
</section>
